 938	// updateAddrs updates ac.addrs with the new addresses list and handles active
 939	// connections or connection attempts.
 940	func (ac *addrConn) updateAddrs(addrs []resolver.Address) {
 941		addrs = copyAddressesWithoutBalancerAttributes(addrs)
 942		limit := len(addrs)
 943		if limit > 5 {
 944			limit = 5
 945		}
 946		channelz.Infof(logger, ac.channelz, "addrConn: updateAddrs addrs (%d of %d): %v", limit, len(addrs), addrs[:limit])
 947	
 948		ac.mu.Lock()
 949		if equalAddresses(ac.addrs, addrs) {
 950			ac.mu.Unlock()
 951			return
 952		}
 953	
 954		ac.addrs = addrs
 955	
 956		if ac.state == connectivity.Shutdown ||
 957			ac.state == connectivity.TransientFailure ||
 958			ac.state == connectivity.Idle {
 959			// We were not connecting, so do nothing but update the addresses.
 960			ac.mu.Unlock()
 961			return
 962		}
 963	
 964		if ac.state == connectivity.Ready {
 965			// Try to find the connected address.
 966			for _, a := range addrs {
 967				a.ServerName = ac.cc.getServerName(a)
 968				if a.Equal(ac.curAddr) {
 969					// We are connected to a valid address, so do nothing but
 970					// update the addresses.
 971					ac.mu.Unlock()
 972					return
 973				}
 974			}
 975		}
 976	
 977		// We are either connected to the wrong address or currently connecting.
 978		// Stop the current iteration and restart.
 979	
 980		ac.cancel()
 981		ac.ctx, ac.cancel = context.WithCancel(ac.cc.ctx)
 982	
 983		// We have to defer here because GracefulClose => onClose, which requires
 984		// locking ac.mu.
 985		if ac.transport != nil {
 986			defer ac.transport.GracefulClose()
 987			ac.transport = nil
 988		}
 989	
 990		if len(addrs) == 0 {
 991			ac.updateConnectivityState(connectivity.Idle, nil)
 992		}
 993	
 994		// Since we were connecting/connected, we should start a new connection
 995		// attempt.
 996		go ac.resetTransportAndUnlock()
 997	}
