1306	// tryAllAddrs tries to creates a connection to the addresses, and stop when at
1307	// the first successful one. It returns an error if no address was successfully
1308	// connected, or updates ac appropriately with the new transport.
1309	func (ac *addrConn) tryAllAddrs(ctx context.Context, addrs []resolver.Address, connectDeadline time.Time) error {
1310		var firstConnErr error
1311		for _, addr := range addrs {
1312			ac.channelz.ChannelMetrics.Target.Store(&addr.Addr)
1313			if ctx.Err() != nil {
1314				return errConnClosing
1315			}
1316			ac.mu.Lock()
1317	
1318			ac.cc.mu.RLock()
1319			ac.dopts.copts.KeepaliveParams = ac.cc.mkp
1320			ac.cc.mu.RUnlock()
1321	
1322			copts := ac.dopts.copts
1323			if ac.scopts.CredsBundle != nil {
1324				copts.CredsBundle = ac.scopts.CredsBundle
1325			}
1326			ac.mu.Unlock()
1327	
1328			channelz.Infof(logger, ac.channelz, "Subchannel picks a new address %q to connect", addr.Addr)
1329	
1330			err := ac.createTransport(ctx, addr, copts, connectDeadline)
1331			if err == nil {
1332				return nil
1333			}
1334			if firstConnErr == nil {
1335				firstConnErr = err
