1344	// createTransport creates a connection to addr. It returns an error if the
1345	// address was not successfully connected, or updates ac appropriately with the
1346	// new transport.
1347	func (ac *addrConn) createTransport(ctx context.Context, addr resolver.Address, copts transport.ConnectOptions, connectDeadline time.Time) error {
1348		addr.ServerName = ac.cc.getServerName(addr)
1349		hctx, hcancel := context.WithCancel(ctx)
1350	
1351		onClose := func(r transport.GoAwayReason) {
1352			ac.mu.Lock()
1353			defer ac.mu.Unlock()
1354			// adjust params based on GoAwayReason
1355			ac.adjustParams(r)
1356			if ctx.Err() != nil {
1357				// Already shut down or connection attempt canceled.  tearDown() or
1358				// updateAddrs() already cleared the transport and canceled hctx
1359				// via ac.ctx, and we expected this connection to be closed, so do
1360				// nothing here.
1361				return
1362			}
1363			hcancel()
1364			if ac.transport == nil {
1365				// We're still connecting to this address, which could error.  Do
1366				// not update the connectivity state or resolve; these will happen
1367				// at the end of the tryAllAddrs connection loop in the event of an
1368				// error.
1369				return
1370			}
1371			ac.transport = nil
1372			// Refresh the name resolver on any connection loss.
1373			ac.cc.resolveNow(resolver.ResolveNowOptions{})
1374			// Always go idle and wait for the LB policy to initiate a new
1375			// connection attempt.
1376			ac.updateConnectivityState(connectivity.Idle, nil)
1377		}
1378	
1379		connectCtx, cancel := context.WithDeadline(ctx, connectDeadline)
1380		defer cancel()
1381		copts.ChannelzParent = ac.channelz
1382	
1383		newTr, err := transport.NewClientTransport(connectCtx, ac.cc.ctx, addr, copts, onClose)
1384		if err != nil {
1385			if logger.V(2) {
1386				logger.Infof("Creating new client transport to %q: %v", addr, err)
1387			}
1388			// newTr is either nil, or closed.
1389			hcancel()
1390			channelz.Warningf(logger, ac.channelz, "grpc: addrConn.createTransport failed to connect to %s. Err: %v", addr, err)
1391			return err
1392		}
1393	
1394		ac.mu.Lock()
1395		defer ac.mu.Unlock()
1396		if ctx.Err() != nil {
1397			// This can happen if the subConn was removed while in `Connecting`
1398			// state. tearDown() would have set the state to `Shutdown`, but
1399			// would not have closed the transport since ac.transport would not
1400			// have been set at that point.
1401			//
1402			// We run this in a goroutine because newTr.Close() calls onClose()
1403			// inline, which requires locking ac.mu.
1404			//
1405			// The error we pass to Close() is immaterial since there are no open
1406			// streams at this point, so no trailers with error details will be sent
1407			// out. We just need to pass a non-nil error.
1408			//
1409			// This can also happen when updateAddrs is called during a connection
1410			// attempt.
1411			go newTr.Close(transport.ErrConnClosing)
1412			return nil
1413		}
1414		if hctx.Err() != nil {
1415			// onClose was already called for this connection, but the connection
1416			// was successfully established first.  Consider it a success and set
1417			// the new state to Idle.
1418			ac.updateConnectivityState(connectivity.Idle, nil)
1419			return nil
1420		}
1421		ac.curAddr = addr
1422		ac.transport = newTr
1423		ac.startHealthCheck(hctx) // Will set state to READY if appropriate.
1424		return nil
1425	}
1426	
1427	// startHealthCheck starts the health checking stream (RPC) to watch the health
1428	// stats of this connection if health checking is requested and configured.
1429	//
1430	// LB channel health checking is enabled when all requirements below are met:
1431	// 1. it is not disabled by the user with the WithDisableHealthCheck DialOption
1432	// 2. internal.HealthCheckFunc is set by importing the grpc/health package
1433	// 3. a service config with non-empty healthCheckConfig field is provided
1434	// 4. the load balancer requests it
1435	//
1436	// It sets addrConn to READY if the health checking stream is not started.
1437	//
1438	// Caller must hold ac.mu.
1439	func (ac *addrConn) startHealthCheck(ctx context.Context) {
1440		var healthcheckManagingState bool
1441		defer func() {
1442			if !healthcheckManagingState {
1443				ac.updateConnectivityState(connectivity.Ready, nil)
1444			}
1445		}()
1446	
1447		if ac.cc.dopts.disableHealthCheck {
1448			return
1449		}
1450		healthCheckConfig := ac.cc.healthCheckConfig()
1451		if healthCheckConfig == nil {
1452			return
1453		}
1454		if !ac.scopts.HealthCheckEnabled {
1455			return
1456		}
1457		healthCheckFunc := ac.cc.dopts.healthCheckFunc
1458		if healthCheckFunc == nil {
1459			// The health package is not imported to set health check function.
1460			//
1461			// TODO: add a link to the health check doc in the error message.
1462			channelz.Error(logger, ac.channelz, "Health check is requested but health check function is not set.")
1463			return
1464		}
1465	
1466		healthcheckManagingState = true
1467	
1468		// Set up the health check helper functions.
1469		currentTr := ac.transport
1470		newStream := func(method string) (any, error) {
1471			ac.mu.Lock()
1472			if ac.transport != currentTr {
1473				ac.mu.Unlock()
1474				return nil, status.Error(codes.Canceled, "the provided transport is no longer valid to use")
1475			}
1476			ac.mu.Unlock()
1477			return newNonRetryClientStream(ctx, &StreamDesc{ServerStreams: true}, method, currentTr, ac)
1478		}
1479		setConnectivityState := func(s connectivity.State, lastErr error) {
1480			ac.mu.Lock()
1481			defer ac.mu.Unlock()
1482			if ac.transport != currentTr {
1483				return
1484			}
1485			ac.updateConnectivityState(s, lastErr)
1486		}
1487		// Start the health checking stream.
1488		go func() {
1489			err := ac.cc.dopts.healthCheckFunc(ctx, newStream, setConnectivityState, healthCheckConfig.ServiceName)
1490			if err != nil {
1491				if status.Code(err) == codes.Unimplemented {
1492					channelz.Error(logger, ac.channelz, "Subchannel health check is unimplemented at server side, thus health check is disabled")
1493				} else {
1494					channelz.Errorf(logger, ac.channelz, "Health checking failed: %v", err)
1495				}
1496			}
1497		}()
1498	}
